#include "compute/qrx_aura_production_routing.h"
#include <limits.h>
#include <openssl/evp.h>
#include <stdio.h>
#include <string.h>

#define ROUTE_DOMAIN "QRX/AURA/PRODUCTION-ROUTE/V1"
#define TELEMETRY_DOMAIN "QRX/AURA/PRODUCTION-TELEMETRY/V1"
#define CAMPAIGN_DOMAIN "QRX/AURA/WAN-CAMPAIGN/V1"

static int nonempty(const char*s,size_t n){return s&&memchr(s,0,n)&&s[0];}
static uint64_t sat_add(uint64_t a,uint64_t b){return UINT64_MAX-a<b?UINT64_MAX:a+b;}
static uint64_t sat_mul(uint64_t a,uint64_t b){return a&&b>UINT64_MAX/a?UINT64_MAX:a*b;}
static uint32_t clamp_bps(uint64_t v){return v>10000u?10000u:(uint32_t)v;}
static int hash_fields(const char*domain,const void*data,size_t n,char out[65]){if(!domain||!data||!out)return-1;EVP_MD_CTX*m=EVP_MD_CTX_new();uint8_t h[32];unsigned hn=0;int ok=m&&EVP_DigestInit_ex(m,EVP_sha3_256(),NULL)==1&&EVP_DigestUpdate(m,domain,strlen(domain))==1&&EVP_DigestUpdate(m,data,n)==1&&EVP_DigestFinal_ex(m,h,&hn)==1&&hn==32;EVP_MD_CTX_free(m);if(!ok)return-1;static const char x[]="0123456789abcdef";for(int i=0;i<32;i++){out[i*2]=x[h[i]>>4];out[i*2+1]=x[h[i]&15];}out[64]=0;return 0;}
static uint32_t task_quality(const QrxAuraModelCapabilityProfile*m,QrxAuraTaskClass t){switch(t){case QRX_AURA_TASK_CODING:return m->coding_bps;case QRX_AURA_TASK_REASONING:return m->reasoning_bps;case QRX_AURA_TASK_RAG:return m->rag_bps;case QRX_AURA_TASK_TOOL_USE:return m->tool_use_bps;default:return m->quality_bps;}}
static const QrxAuraModelCapabilityProfile*find_model(const QrxAuraModelCapabilityProfile*m,size_t n,const char*id,const char*v){for(size_t i=0;i<n;i++)if(!strcmp(m[i].model_id,id)&&!strcmp(m[i].model_version,v))return&m[i];return NULL;}
int qrx_aura_production_offer_validate(const QrxAuraProductionOffer*o){if(!o||o->version!=1||!nonempty(o->provider_id,sizeof(o->provider_id))||!nonempty(o->pod_id,sizeof(o->pod_id))||!nonempty(o->region,sizeof(o->region))||!nonempty(o->model_id,sizeof(o->model_id))||!nonempty(o->model_version,sizeof(o->model_version))||o->backend<QRX_MOE_BACKEND_CPU||o->backend>QRX_MOE_BACKEND_OTHER||o->reliability_bps>10000||o->observed_quality_bps>10000)return-1;if(o->available&&!o->milli_tokens_per_second)return-2;return 0;}
static void weights(QrxAuraProductionOptimization o,uint32_t*wq,uint32_t*wl,uint32_t*wc,uint32_t*we,uint32_t*wr,uint32_t*wo){if(o==QRX_AURA_OPT_ECO){*wq=25;*wl=10;*wc=25;*we=25;*wr=10;*wo=5;}else if(o==QRX_AURA_OPT_PERFORMANCE){*wq=45;*wl=30;*wc=5;*we=5;*wr=10;*wo=5;}else{*wq=35;*wl=20;*wc=15;*we=10;*wr=15;*wo=5;}}
static uint32_t inverse_score(uint64_t value,uint64_t ceiling){if(!ceiling)return value?0:10000;if(value>=ceiling)return value==ceiling?1:0;return clamp_bps(((ceiling-value)*10000u)/ceiling);}
int qrx_aura_production_route(const QrxAuraProductionRouteRequest*r,const QrxAuraModelCapabilityProfile*m,size_t mn,const QrxAuraProductionOffer*o,size_t on,QrxAuraProductionRouteDecision*out){if(!r||!m||!mn||!o||!on||!out||r->version!=1||r->task_class<QRX_AURA_TASK_CHAT||r->task_class>QRX_AURA_TASK_TOOL_USE||r->optimization<QRX_AURA_OPT_ECO||r->optimization>QRX_AURA_OPT_PERFORMANCE||r->min_quality_bps>10000||r->min_reliability_bps>10000)return-1;uint32_t wq,wl,wc,we,wr,wo;weights(r->optimization,&wq,&wl,&wc,&we,&wr,&wo);int found=0;QrxAuraProductionRouteDecision best;memset(&best,0,sizeof(best));for(size_t i=0;i<on;i++){const QrxAuraProductionOffer*x=&o[i];if(qrx_aura_production_offer_validate(x)||!x->available)continue;const QrxAuraModelCapabilityProfile*mp=find_model(m,mn,x->model_id,x->model_version);if(!mp||qrx_aura_model_profile_validate(mp))continue;uint32_t tq=task_quality(mp,r->task_class);uint32_t observed=x->observed_quality_bps?x->observed_quality_bps:tq;uint32_t effective=tq<observed?tq:observed;if(effective<r->min_quality_bps||x->reliability_bps<r->min_reliability_bps||mp->max_context_tokens<r->min_context_tokens)continue;if(r->max_latency_ms&&x->latency_ms>r->max_latency_ms)continue;if(r->max_price_microqub_per_million_tokens&&x->price_microqub_per_million_tokens>r->max_price_microqub_per_million_tokens)continue;if(r->max_energy_mwh_per_1000_tokens&&x->energy_mwh_per_1000_tokens>r->max_energy_mwh_per_1000_tokens)continue;int local=!r->preferred_region[0]||!strcmp(r->preferred_region,x->region);if(!local&&!r->allow_cross_region)continue;uint64_t latceil=r->max_latency_ms?r->max_latency_ms:1000;uint64_t costceil=r->max_price_microqub_per_million_tokens?r->max_price_microqub_per_million_tokens:(x->price_microqub_per_million_tokens?x->price_microqub_per_million_tokens*4u:1u);uint64_t energyceil=r->max_energy_mwh_per_1000_tokens?r->max_energy_mwh_per_1000_tokens:(x->energy_mwh_per_1000_tokens?x->energy_mwh_per_1000_tokens*4u:1u);uint32_t ls=inverse_score(x->latency_ms,latceil),cs=inverse_score(x->price_microqub_per_million_tokens,costceil),es=inverse_score(x->energy_mwh_per_1000_tokens,energyceil),loc=local?10000:2500;uint64_t score=(uint64_t)effective*wq+(uint64_t)ls*wl+(uint64_t)cs*wc+(uint64_t)es*we+(uint64_t)x->reliability_bps*wr+(uint64_t)loc*wo;score/=100u;if(r->optimization==QRX_AURA_OPT_PERFORMANCE)score+=x->milli_tokens_per_second/100000u;if(score>UINT32_MAX)score=UINT32_MAX;if(!found||score>best.total_score||(score==best.total_score&&strcmp(x->provider_id,best.provider_id)<0)){memset(&best,0,sizeof(best));best.version=1;best.offer_index=(uint32_t)i;snprintf(best.provider_id,sizeof(best.provider_id),"%s",x->provider_id);snprintf(best.pod_id,sizeof(best.pod_id),"%s",x->pod_id);snprintf(best.region,sizeof(best.region),"%s",x->region);snprintf(best.model_id,sizeof(best.model_id),"%s",x->model_id);snprintf(best.model_version,sizeof(best.model_version),"%s",x->model_version);best.total_score=(uint32_t)score;best.task_quality_bps=tq;best.observed_quality_bps=observed;best.latency_score_bps=ls;best.cost_score_bps=cs;best.energy_score_bps=es;best.reliability_score_bps=x->reliability_bps;best.locality_score_bps=loc;best.price_microqub_per_million_tokens=x->price_microqub_per_million_tokens;best.energy_mwh_per_1000_tokens=x->energy_mwh_per_1000_tokens;best.milli_tokens_per_second=x->milli_tokens_per_second;found=1;}}
    if(!found)return -2;
    if(qrx_aura_production_route_commitment(&best,best.decision_commitment))return -3;
    *out=best;
    return 0;
}
int qrx_aura_production_route_commitment(const QrxAuraProductionRouteDecision*d,char out[65]){if(!d||d->version!=1||!nonempty(d->provider_id,sizeof(d->provider_id))||!nonempty(d->model_id,sizeof(d->model_id)))return-1;QrxAuraProductionRouteDecision c=*d;c.decision_commitment[0]=0;return hash_fields(ROUTE_DOMAIN,&c,sizeof(c),out);}
void qrx_aura_production_telemetry_init(QrxAuraProductionTelemetry*t,const char*p,const char*m,const char*v){if(!t)return;memset(t,0,sizeof(*t));t->version=1;if(p)snprintf(t->provider_id,sizeof(t->provider_id),"%s",p);if(m)snprintf(t->model_id,sizeof(t->model_id),"%s",m);if(v)snprintf(t->model_version,sizeof(t->model_version),"%s",v);}
int qrx_aura_production_telemetry_record(QrxAuraProductionTelemetry*t,uint64_t tokens,uint32_t lat,uint32_t q,uint64_t cost,uint64_t energy,uint64_t wan,uint8_t failed){if(!t||t->version!=1||!nonempty(t->provider_id,sizeof(t->provider_id))||!tokens||q>10000)return-1;t->requests=sat_add(t->requests,1);t->tokens=sat_add(t->tokens,tokens);t->latency_ms_total=sat_add(t->latency_ms_total,lat);t->quality_bps_token_sum=sat_add(t->quality_bps_token_sum,sat_mul(q,tokens));t->cost_microqub_total=sat_add(t->cost_microqub_total,cost);t->energy_mwh_total=sat_add(t->energy_mwh_total,energy);t->wan_bytes=sat_add(t->wan_bytes,wan);t->failed=sat_add(t->failed,failed?1:0);return 0;}
uint32_t qrx_aura_production_telemetry_failure_bps(const QrxAuraProductionTelemetry*t){if(!t||t->version!=1||!t->requests)return 0;return clamp_bps((t->failed*10000u)/t->requests);}
uint32_t qrx_aura_production_telemetry_avg_quality_bps(const QrxAuraProductionTelemetry*t){if(!t||t->version!=1||!t->tokens)return 0;return clamp_bps(t->quality_bps_token_sum/t->tokens);}
uint32_t qrx_aura_production_telemetry_avg_latency_ms(const QrxAuraProductionTelemetry*t){if(!t||t->version!=1||!t->requests)return 0;uint64_t v=t->latency_ms_total/t->requests;return v>UINT32_MAX?UINT32_MAX:(uint32_t)v;}
int qrx_aura_production_telemetry_commitment(const QrxAuraProductionTelemetry*t,char out[65]){if(!t||t->version!=1||!nonempty(t->provider_id,sizeof(t->provider_id)))return-1;return hash_fields(TELEMETRY_DOMAIN,t,sizeof(*t),out);}
int qrx_aura_production_campaign_run(const QrxAuraProductionRouteRequest*tasks,size_t tn,const QrxAuraModelCapabilityProfile*m,size_t mn,const QrxAuraProductionOffer*o,size_t on,QrxAuraProductionCampaignResult*out){if(!tasks||!tn||tn>QRX_AURA_PRODUCTION_MAX_CAMPAIGN_TASKS||!m||!o||!out)return-1;QrxAuraProductionCampaignResult r;memset(&r,0,sizeof(r));r.version=1;r.tasks_total=tn;for(size_t i=0;i<tn;i++){QrxAuraProductionRouteDecision d;if(qrx_aura_production_route(&tasks[i],m,mn,o,on,&d)){r.tasks_failed++;continue;}r.tasks_routed++;if(tasks[i].preferred_region[0]&&strcmp(tasks[i].preferred_region,d.region))r.cross_region_routes++;r.aggregate_score=sat_add(r.aggregate_score,d.total_score);r.aggregate_price_microqub_per_million_tokens=sat_add(r.aggregate_price_microqub_per_million_tokens,d.price_microqub_per_million_tokens);r.aggregate_energy_mwh_per_1000_tokens=sat_add(r.aggregate_energy_mwh_per_1000_tokens,d.energy_mwh_per_1000_tokens);r.aggregate_latency_ms=sat_add(r.aggregate_latency_ms,o[d.offer_index].latency_ms);}QrxAuraProductionCampaignResult c=r;c.campaign_commitment[0]=0;if(hash_fields(CAMPAIGN_DOMAIN,&c,sizeof(c),r.campaign_commitment))return-2;*out=r;return 0;}
